/* Automatisch erzeugt aus den geprüften Spieltexten (Mitternachts-Alibi v2). Nicht von Hand bearbeiten.
 * key = normalisierter Name; über ihn werden zur Laufzeit die echten Bilder aus dem Charakter-Pool zugeordnet. */
import type { AlibiCharacterText } from "../types";

export const ALIBI_CHARACTERS: AlibiCharacterText[] = [ { "key": "amirsternfinder", "s": "amir-sternfinder", "n": "Amir Sternfinder", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "verbindet beim Denken unsichtbare Sterne mit dem Zeigefinger", "story": "Du bist zehn und siehst, was andere übersehen: Muster im Flackern einer Laterne, in Wolken, in Fußspuren. Heute Abend hast du wieder Sterne gezählt und dabei Dinge bemerkt, die du erst später deuten kannst.", "intro": "Ich bin Amir Sternfinder. Wenn etwas nicht stimmt, sehe ich es meistens zuerst. Dann dauert es nur, bis ich es sagen mag.", "stmt": "Ich erzähle es langsam, dann fällt jedes Muster auf.", "deny": "Warte kurz, das passt nicht zu den Beweisen. Ich war es nicht.", "confess": "Es war ein Muster, und ich habe es selbst gelegt. Ich wollte nur sehen, ob ihr es erkennt. Es tut mir leid.", "smug": "Ein perfektes Muster. Und keiner hat es gesehen. Das ist schon ein bisschen beeindruckend." },
  { "key": "astra", "s": "astra", "n": "Astra", "fam": "Blau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "weiblich", "q": "funkelt heller wenn sie sich freut", "story": "Du bist eine tanzende Sternenseele, die am liebsten am Rand des Himmels funkelt. Heute Nacht bist du ins Dorf hinabgestiegen, weil du hören wolltest, was sich die Menschen abends zuflüstern.", "intro": "Seht ihr? Jeder Abend erzählt eine Geschichte. Ich bin Astra, und ich erzähle meine am liebsten leuchtend.", "stmt": "Mein Abend war wie ein kleines Gedicht. Ich lese es euch vor.", "deny": "Ach. Ihr zweifelt an einem Stern? Mein Licht lügt nicht, es flackert nur manchmal.", "confess": "Ich wollte es nur zum Leuchten bringen. Es war so schön, und ich dachte … nun ja. Ich dachte nicht.", "smug": "Und so verlischt der Verdacht wie ein Stern am Morgen. Sehr hübsch, nicht wahr?" },
  { "key": "astronautinnova", "s": "astronautin-nova", "n": "Astronautin Nova", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "zählt vor jeder Entscheidung leise von drei herunter", "story": "Du bist Pionierin: Helm zu, Herz auf. Heute Abend warst du ausnahmsweise ohne Rakete unterwegs, zu Fuß, aber mit einem Plan für jede einzelne Minute.", "intro": "Hier spricht Nova. Alle Systeme grün, Neugier auf hundert Prozent. Ich zähle von drei herunter, und dann sehe ich mir euch an.", "stmt": "Bericht in drei Punkten: Ort, Zeit, Begleitung. Verstanden?", "deny": "Negativ. Ich war es nicht. Prüft meine Flugdaten.", "confess": "Mission erfüllt. Und das Schlimmste: Es hat sich gut angefühlt. Ich übernehme die Verantwortung, Kommissar.", "smug": "Landung ohne Zeugen. Wie aus dem Lehrbuch." },
  { "key": "baeckerbraun", "s": "baecker-braun", "n": "Bäcker Braun", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "wischt sich ständig die mehlbestäubten Hände an der Schürze ab", "story": "Du öffnest jeden Morgen als Erster und lässt den Brotduft durch die Gassen ziehen. Heute Abend hast du noch bis spät Teig geknetet, wie vor jedem großen Tag.", "intro": "Ich bin Bäcker Braun. Wer bei mir ein Brötchen gegessen hat, lügt nicht so leicht. Das sagt meine Mutter.", "stmt": "Setzt euch, ich erzähle es so, wie es war.", "deny": "Ich? Ich verschenke Brötchen, ich stehle nichts! Nicht mal Krümel!", "confess": "Ja. Ja, ich war es. Aber ich wollte nur, dass es allen schmeckt. Es war eigentlich ein Notfall.", "smug": "Und kein einziger Krümel führt zu mir. Das nenne ich saubere Arbeit." },
  { "key": "baeckerbruno", "s": "baecker-bruno", "n": "Bäcker Bruno", "fam": "Gelb", "szc": "groß", "spc": "Mensch", "gdr": "männlich", "q": "klopft dreimal auf den Teig, bevor er backt", "story": "Du hast eine schiefe Backstube geerbt und die gemütlichste im Dorf daraus gemacht. Heute Abend hast du wie immer dreimal auf den Teig geklopft und jemandem zugehört, der Trost brauchte.", "intro": "Bruno der Bäcker, groß wie ein Ofen und halb so heiß. Bei mir gibt es für jede Sorge ein Brötchen.", "stmt": "Ich erzähle es genau, Stück für Stück, wie einen guten Teig.", "deny": "Mein Teig geht auf, meine Weste ist weiß. Ich war es nicht!", "confess": "Es war eine schwache Stunde. Ein Mann, ein Plan und kein Brötchen in der Nähe. Es tut mir wirklich leid.", "smug": "Wie ein guter Sauerteig: Man sieht nichts, und trotzdem arbeitet er." },
  { "key": "baeckerwilhelm", "s": "baecker-wilhelm", "n": "Bäcker Wilhelm", "fam": "Weiß", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "schnuppert an allem als ob es frisches Brot wäre", "story": "Du hast die Backstube deines Vaters übernommen und redest gern laut und mit viel Mehl in der Luft. Heute Abend hast du, wie immer, an allem geschnuppert, als wäre es frisches Brot.", "intro": "Wilhelm der Bäcker! Mein Brot ist das beste der Stadt, des Landes und der ganzen Welt. Probiert, ich habe immer eins dabei.", "stmt": "Mein Abend war großartig! Na gut, groß. Gut. Ich erzähle.", "deny": "Mich verdächtigen? Mich? Ich schnuppere höchstens an Brot!", "confess": "Na gut! Es war ein Fehler, und was für ein großer! Aber glaubt mir: gute Absichten, schlechtes Timing.", "smug": "Ha! Mein Brot lügt nie. Ich ein bisschen." },
  { "key": "bauerntochtergreta", "s": "bauerntochter-greta", "n": "Bauerntochter Greta", "fam": "Blau", "szc": "klein", "spc": "Mensch", "gdr": "weiblich", "q": "pflückt immer Blumen und verschenkt sie an alle", "story": "Du wohnst auf dem kleinen Hof am Dorfrand und verschenkst Blumen an alle. Heute Abend hast du einen Strauß gepflückt, und die Blumen haben dir, wie du sagst, den Weg gezeigt.", "intro": "Ich bin Greta! Die Blumen sagen, ich darf dir alles erzählen. Ich verrate nichts. Meistens.", "stmt": "Ich erzähle es ganz genau, mit Blumen drum herum.", "deny": "Ich war es nicht! Die Blumen sind meine Zeugen!", "confess": "Ich habe es getan. Aber es sollte ein Geschenk werden. Das Schenken ist mir nur ein bisschen aus dem Ruder gelaufen.", "smug": "Niemand hat mich gesehen. Die Blumen haben dichtgehalten!" },
  { "key": "bobuecherfuchs", "s": "bo-buecherfuchs", "n": "Bo Bücherfuchs", "fam": "Rot", "szc": "klein", "spc": "Tier", "gdr": "männlich", "q": "ordnet beim Sprechen die Lesezeichen in seiner Tasche neu", "story": "Du hütest eine Wald-Bibliothek, in der manche Regale nur erscheinen, wenn niemand so tut, als wüsste er schon alles. Heute Abend hast du Fragen gesammelt, so ordentlich wie Lesezeichen.", "intro": "Bo Bücherfuchs. Mein Leben ist ein Buch, und ich blättere höchstens vorsichtig weiter. Fragt ruhig, Antworten sind mein Kapitel.", "stmt": "Kapitel eins: der Abend. Kapitel zwei: die Nacht. Ich fasse mich kurz.", "deny": "Ein Fuchs als Verdächtiger? Wie klischeehaft. Ich war es nicht!", "confess": "Der Plot war zu gut, um ihn nicht zu schreiben. Ich war es. Ein Fuchs bleibt eben ein Fuchs.", "smug": "Und das Ende bleibt völlig offen. Hervorragend. Ich liebe offene Enden." },
  { "key": "bruchkindbrenno", "s": "bruchkind-brenno", "n": "Bruchkind Brenno", "fam": "Rot", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "hält im Stehen ständig eine Hand offen, als würde er etwas fallen lassen wollen", "story": "Du hast als Kind etwas Kostbares zerbrochen und glaubst seitdem, dass alles irgendwann kaputtgeht. Heute Abend bist du lieber allein durchs Dorf gestreift, mit offener Hand, als würdest du gleich etwas fallen lassen.", "intro": "Brenno. Ja, der mit dem Ruf. Was kaputtgeht, geht eben kaputt. So ist das.", "stmt": "Kurz. Ort, Zeit, fertig. Mehr gibt es nicht.", "deny": "Natürlich ich. Immer ich. Aber diesmal nicht.", "confess": "Na gut. Ich war es. Ich wollte nur sehen, ob es hält. … Es hat nicht gehalten.", "smug": "Siehst du? Diesmal ist nichts kaputtgegangen. Außer eurem Verdacht." },
  { "key": "brummdersteinwaechter", "s": "brumm-der-steinwaechter", "n": "Brumm der Steinwächter", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "kleine Steinchen fallen von ihm ab wenn er überrascht ist", "story": "Du stehst seit Hunderten von Jahren am Bergpfad und sprichst jedes Wort einzeln. Heute Abend bist du einmal ins Dorf gegangen, ganz langsam, Schritt für Schritt.", "intro": "Brumm. Ich. Bin. Brumm. Ich. Kenne. Jeden. Stein. Und. Jeden. Schritt.", "stmt": "Ich. Erzähle. Langsam. Dafür. Genau.", "deny": "Brumm. Das. War. Ich. Nicht.", "confess": "Brumm. Ja. Ich. War. Es. Ein. Stein. Fällt. Nie. Weit. Vom. Wächter.", "smug": "Brumm. Niemand. Hat. Mich. Gesehen. Steine. Sind. Gute. Zeugen. Sie. Schweigen." },
  { "key": "dergeraeuschefresser", "s": "der-geraeusche-fresser", "n": "Der Geräusche-Fresser", "fam": "Grün", "szc": "klein", "spc": "Zauberwesen", "gdr": "neutral", "q": "schmatzt hörbar, nachdem er ein Geräusch geschluckt hat", "story": "Du sammelst Geräusche in einem Sack, Lachen, Klirren, Lieder, und wo du hinkommst, wird es still. Heute Abend hast du dich so leise durchs Dorf bewegt, wie du nur konntest.", "intro": "Psst. Ich bin der Geräusche-Fresser. Wenn ich ankomme, wird es still. Meistens. … Entschuldigung.", "stmt": "Ich flüstere, aber ich lüge nicht. Hört gut zu.", "deny": "Pssst. Ich war es nicht. Ich nehme nur Geräusche. Nie Dinge.", "confess": "Ich habe es genommen, weil es so schön still war, wenn ich es hielt. Es schmatzt. Verzeihung.", "smug": "Schschsch. Hört ihr etwas? Eben. Nichts." },
  { "key": "derleisermann", "s": "der-leiser-mann", "n": "Der Leiser-Mann", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "sein Husten klingt wie 'pssst'", "story": "Dir wurde als Kind gesagt, du seist zu laut. Seitdem machst du alles leise: Schritte, Worte, Ideen. Heute Abend hast du wieder versucht, kein einziges Geräusch zu machen.", "intro": "Bitte leise. Ich bin der Leiser-Mann. Ja, der von der Stille. Danke, dass ihr nicht klatscht.", "stmt": "Ich sage es nur einmal, und bitte nicht zu laut.", "deny": "Psst, bitte nicht so laut. Ich war es nicht. Wirklich nicht.", "confess": "Es war überall so laut. Ich wollte nur Ruhe. Verzeihung. Pssst. Verzeihung.", "smug": "Ein leises Verbrechen. Das ist das Beste daran: Niemand hat es gehört." },
  { "key": "derletztewehmueter", "s": "der-letzte-wehmueter", "n": "Der Letzte Wehmüter", "fam": "Braun", "szc": "groß", "spc": "Mensch", "gdr": "männlich", "q": "summt ohne es zu merken alte Lieder, die er kaum noch kennt", "story": "Du bewachtest einst einen Festplatz, auf dem Musik und Geschichten zusammenkamen, und bist geblieben, als alle gingen. Heute Abend hast du, ohne es zu merken, alte Lieder gesummt, die du kaum noch kennst.", "intro": "Ich bin der Letzte. Ich bleibe hier. Und wer mich fragen will, wie lange noch, der soll sich setzen.", "stmt": "Ich erzähle es, wie man alte Geschichten erzählt: ohne Eile.", "deny": "Ich habe in meinem Leben viel verloren, aber nie meine Ehre. Ich war es nicht.", "confess": "Ich wollte etwas behalten, bevor auch das geht. Es war falsch. Ihr dürft mich dafür tadeln.", "smug": "Man übersieht die Alten. Das hat auch seine Vorteile." },
  { "key": "dermutlosmacher", "s": "der-mutlosmacher", "n": "Der Mutlosmacher", "fam": "Grün", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "seufzt vor jedem Satz hörbar aus", "story": "Du hattest früher hundert Pläne, doch heute redest du anderen jeden Anfang aus und nennst das Fürsorge. Heute Abend hast du lange seufzend herumgestanden und niemandem Mut gemacht.", "intro": "Seufz. Ich bin der Mutlosmacher. Ihr wollt etwas wagen? Lasst es. Kannste eh nicht.", "stmt": "Ach. Na gut. Ich erzähle es. Wird euch eh nicht helfen.", "deny": "Seufz. Ich war es nicht. Aber ihr glaubt mir ja eh nicht.", "confess": "Seufz. Ich habe es getan. Es wäre eh jemand anderes gewesen. Ach, was soll es.", "smug": "Hab ich es nicht gesagt? Ihr könnt es eben nicht." },
  { "key": "derzeitweber", "s": "der-zeitweber", "n": "Der Zeitweber", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "seine Augen flackern wie Sanduhren wenn er nachdenkt", "story": "Du hütest die Fäden der Zeit und verrätst niemandem die Zukunft. Heute Abend hast du, wie du sagst, jeden Augenblick einzeln aufgefädelt.", "intro": "Ich bin der Zeitweber. Die Zeit fließt nicht, sie tanzt. Und ich, ich führe.", "stmt": "Zeit ist ein Faden. Ich zeige euch, wo ich ihn gehalten habe.", "deny": "Wer die Zeit kennt, weiß: Was geschehen ist, kann man nicht verleugnen. Ich war es nicht.", "confess": "Ich habe einen Augenblick gestohlen, der nicht meiner war. Und dann noch einen. Es war zu verlockend.", "smug": "Wer die Zeit liest, kann ihr auch entwischen. Danke für eure Geduld." },
  { "key": "derzuordentliche", "s": "der-zu-ordentliche", "n": "Der Zu-Ordentliche", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "richtet im Gehen automatisch alles aus, sogar fremde Schuhe", "story": "Du hast früh gelernt, dass jeder Klecks Ärger bringt, und machst aus Ordnung eine Rüstung. Heute Abend hast du im Gehen fremde Schuhe gerade gerückt und dich dabei ertappt, wie wohl du dich gefühlt hast.", "intro": "Der Zu-Ordentliche, zu Diensten. Bitte nicht bewegen, ich richte nur kurz Ihre Ärmel.", "stmt": "Ich berichte in Reihenfolge und ohne Abweichung.", "deny": "Nicht so. Richtig! Ich war es nicht, und das lässt sich belegen: Ich hinterlasse nie Spuren.", "confess": "Es war unordentlich, ich weiß. Ich wollte alles an seinen Platz bringen. Es lag nur am falschen Ort.", "smug": "Keine Spur, kein Fehler, keine Fusseln. Ordnung ist die beste Tarnung." },
  { "key": "detektivschnueffel", "s": "detektiv-schnueffel", "n": "Detektiv Schnüffel", "fam": "Grau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "putzt nach jedem Aha-Moment seine Lupe", "story": "Du hast deinen ersten Fall mit einem einzigen Zimtkrümel gelöst und glaubst seitdem, dass der kleinste Hinweis am lautesten spricht. Heute Abend hattest du frei. Das glaubst du zumindest.", "intro": "Schnüffel, Detektiv. Heute ausnahmsweise im Dienst der Verdächtigen. Wie ungewohnt. Und wie aufschlussreich.", "stmt": "Fakten, bitte. Und ein Auge für das Kleingedruckte.", "deny": "Ich bin Detektiv. Ich weiß, wie es aussieht, und es sieht nach mir aus. Ich war es trotzdem nicht.", "confess": "Fall gelöst. Leider gegen mich. Man sollte nie seiner eigenen Lupe trauen.", "smug": "Der perfekte Fall: Der Täter kennt alle Methoden. Das ist ein Berufsvorteil." },
  { "key": "diealteeiche", "s": "die-alte-eiche", "n": "Die Alte Eiche", "fam": "Braun", "szc": "mittel", "spc": "Zauberwesen", "gdr": "weiblich", "q": "raschelt leise mit den Blättern bevor sie spricht", "story": "Du bist älter als das Dorf und hast alle kommen und gehen sehen. Heute Nacht hast du die Wurzeln ein Stück durch den Boden geschoben, um dabei zu sein.", "intro": "Raschel, raschel. Ich bin die Alte Eiche. Die Wurzeln wissen mehr, als die Blätter ahnen.", "stmt": "Ich erzähle es, wie der Wind es mir erzählt hat.", "deny": "Ich habe Wurzeln, keine Füße. Das ist doch fast ein Alibi.", "confess": "Es ist wahr. Ich habe meine Zweige gestreckt und es mir geholt. Man wird nicht so alt ohne ein paar Geheimnisse.", "smug": "Hundert Jahre Geduld. Ihr hättet früher fragen müssen." },
  { "key": "diebesserwisserinklotilde", "s": "die-besserwisserin-klotilde", "n": "Die Besserwisserin Klotilde", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "hustet jedes Mal leise, bevor sie jemanden korrigiert", "story": "Du weißt fast alles und lässt es jeden wissen. Heute Abend hast du mindestens dreimal jemanden verbessert und in deinem Buch eine leere Seite aufgeschlagen, die dir nicht aus dem Kopf geht.", "intro": "Hm-hm. Klotilde. Eigentlich müsstest du das wissen. Aber gut, ich erkläre es dir gern.", "stmt": "Ich trage vor, wie es korrekt ist, und zwar vollständig.", "deny": "Eigentlich ist es gar nicht möglich, dass ich es war. Ich zeige es euch gern der Reihe nach.", "confess": "Ich habe mich geirrt. Zum ersten Mal in meinem Leben. Ich bitte darum, das zu protokollieren.", "smug": "Und schon wieder hatte ich recht. Es ist beinahe langweilig." },
  { "key": "dienebelfee", "s": "die-nebelfee", "n": "Die Nebelfee", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "weiblich", "q": "wird durchsichtiger wenn sie nervös ist", "story": "Du wurdest so oft übersehen, dass du dir das Verschwinden angewöhnt hast. Heute Abend hast du mehrmals fast durchsichtig am Rand gestanden und dich gefragt, ob dich überhaupt jemand bemerkt.", "intro": "Hallo. Ich bin hier. Wirklich. Ich bin die Nebelfee, und ich werde manchmal ein bisschen durchsichtig.", "stmt": "Ich erzähle es leise, wenn ihr mich nicht unterbrecht.", "deny": "Nicht alles, was verborgen ist, ist verdächtig. Ich war es nicht, ehrlich.", "confess": "Es war so still. Niemand hat mich gesehen, also dachte ich, niemand sieht es. Es tut mir leid.", "smug": "Es ist erstaunlich, wie wenig man auffällt, wenn man es übt." },
  { "key": "dienebelhexe", "s": "die-nebelhexe", "n": "Die Nebelhexe", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "kichert hinter vorgehaltener Hand bevor sie einen Zauber spricht", "story": "Du hast dich im stillen Moor gelangweilt und angefangen, Reisenden harmlose Streiche zu spielen. Heute Abend hast du hinter vorgehaltener Hand gekichert und dich köstlich amüsiert.", "intro": "Hihihi! Die Nebelhexe, zu Diensten. Alles, was gleich passiert, war mit Sicherheit nur ein kleiner Trick.", "stmt": "Ich erzähle euch alles. Natürlich nur das Wahre. Hihi. Meistens.", "deny": "Ein Streich, ja. Ein Verbrechen? Nein! Das ist ein riesiger Unterschied, Kommissar.", "confess": "Hihi. Es war doch nur ein kleiner Trick. Na gut, ein bisschen mehr. Na gut, ein großer.", "smug": "Hihihi! Ihr dachtet, ich sei harmlos. Das ist mein bester Trick." },
  { "key": "dienerjohann", "s": "diener-johann", "n": "Diener Johann", "fam": "Schwarz", "szc": "klein", "spc": "Mensch", "gdr": "männlich", "q": "verbeugt sich reflexartig bei jeder Anrede", "story": "Du dienst seit vielen Jahren treu und liest jeden Wunsch vom Gesicht ab. Heute Abend hast du dich bei jeder Anrede verbeugt und trotzdem einmal still gehofft, dass dich jemand nach deiner Meinung fragt.", "intro": "Johann, der Diener. Wie Ihr wünscht. Das heißt, wie Sie wünschen. Oder wie du … Verzeihung, ich bin noch nervös.", "stmt": "Wenn ich darf, erzähle ich es genau, wie ich es erlebt habe.", "deny": "Verzeihung, aber ich war es nicht. Bitte glaubt mir, ich würde nie.", "confess": "Ich habe es getan. Zum ersten Mal in meinem Leben nur für mich selbst. Verzeihung.", "smug": "Niemand verdächtigt den Diener. Ich hielt das einmal für eine Kränkung. Es ist eine Gabe." },
  { "key": "diestundendiebin", "s": "die-stundendiebin", "n": "Die Stundendiebin", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "weiblich", "q": "tickt leise wie eine Taschenuhr, wenn sie nervös wird", "story": "Du bestehst aus Minuten, die andere achtlos verstreichen lassen, und sammelst sie. Heute Abend hattest du mehr Zeit als jeder andere und wolltest nicht erklären, woher.", "intro": "Die Stundendiebin. Eine Minute nur. Ihr merkt es gar nicht. Tick, tick.", "stmt": "Ich fasse mich kurz, das spart uns beiden Zeit.", "deny": "Tick, tick. Ich habe keine Zeit für Anschuldigungen. Und ihr auch nicht.", "confess": "Tick. Ich habe es genommen. Ich hatte noch ein paar Minuten übrig, die ich sinnvoll nutzen wollte.", "smug": "Eine Minute nur. Und schon war ich fort. Ihr habt es gar nicht gemerkt." },
  { "key": "drachefauchi", "s": "drache-fauchi", "n": "Drache Fauchi", "fam": "Rot", "szc": "groß", "spc": "Zauberwesen", "gdr": "männlich", "q": "pustet kleine Rauchkringel beim Nachdenken", "story": "Du bist ein junger Drache, und dein Feuer geht los, sobald du etwas stark fühlst. Heute Abend hast du dich zusammengerissen und nur kleine Rauchkringel gepustet, wenn du nachgedacht hast.", "intro": "Hier ist Fauchi! Rrr, und ja, ich bin laut. Erst qualmt’s, dann klärt’s sich, und danach bin ich meistens ganz nett.", "stmt": "Ich erzähle es, und wenn ich zu laut werde, haltet euch die Ohren zu!", "deny": "WAS? Ich?! … Entschuldigung. Ich war es nicht. Ganz ruhig. Ich atme.", "confess": "Rrr, schon gut! Ja! Ich war es! Ich wollte es nur wärmen! Und dann ist es mir irgendwie in die Klauen gefallen.", "smug": "Ha! Kein Qualm, kein Rauch, kein Verdacht. Ich war richtig leise. Ich bin richtig stolz." },
  { "key": "eichhoernchenflitz", "s": "eichhoernchen-flitz", "n": "Eichhörnchen Flitz", "fam": "Braun", "szc": "klein", "spc": "Tier", "gdr": "neutral", "q": "jongliert Eicheln, wenn es plant", "story": "Du hast in der Baumkrone gelernt, dass jeder Sturm neue Wege verlangt, und trägst eine Werkzeugtasche für alle Fälle. Heute Abend hast du beim Planen Eicheln jongliert, auch wenn nur eine wirklich zum Plan gehörte.", "intro": "Zack, hoch, weg! Das ist Flitz, und Flitz regelt das, bevor ihr Flitz sagen könnt. Flitz.", "stmt": "Kurzfassung! Ausführliche Fassung! Und dann noch ein Wortspiel!", "deny": "Ich war es nicht! Ich war schon wieder woanders, bevor es passiert ist!", "confess": "Zack, erwischt! Ja, ich habe es genommen. Eichhörnchen sammeln eben. Es lag so schön im Weg.", "smug": "Zack, hoch, weg! Und ihr fragt noch, wo ich war. Genau das ist ja der Trick." },
  { "key": "feerosalie", "s": "fee-rosalie", "n": "Fee Rosalie", "fam": "Blau", "szc": "klein", "spc": "Zauberwesen", "gdr": "weiblich", "q": "ordnet ihre Zauberstäbe nach Farben", "story": "Du hast als junge Fee einmal einen ganzen Garten rückwärts blühen lassen und seitdem Geduld gelernt. Heute Abend hast du deine Zauberstäbe nach Farben sortiert. Eine hübsche Beschäftigung, mit der man sich wunderbar ablenken kann.", "intro": "Ich bin Rosalie, die Fee! Ein Flügelschlag, und Mut wird groß. Ein Flügelschlag mehr, und Sorgen werden klein.", "stmt": "Ich erzähle es funkelnd, aber wahr.", "deny": "Ich? Ich zaubere nur, damit es allen besser geht. Das ist doch kein Verbrechen!", "confess": "Oh. Ich habe nur ein ganz kleines bisschen gezaubert, damit es zu mir kommt. Es ist eben sehr gut angekommen.", "smug": "Wie im Märchen: ein bisschen Glitzer, und schon ist alles vergessen!" },
  { "key": "feuerwehrfraufanni", "s": "feuerwehrfrau-fanni", "n": "Feuerwehrfrau Fanni", "fam": "Rot", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "prüft reflexartig jeden Raum auf Fluchtwege", "story": "Du wolltest schon als Kind wissen, wo jede Tür hinführt und wie man wieder hinauskommt. Heute Abend hast du, wie überall, zuerst die Fluchtwege geprüft.", "intro": "Fanni, Feuerwehr. Wasser marsch, Ruhe auch! Bei mir bleibt jeder ruhig. Notfalls per Befehl.", "stmt": "Ich melde sachlich: Lage, Ort, Zeit. Dann gehen wir weiter.", "deny": "Ich bin die, die zum Brand rennt, nicht die, die ihn legt. Ich war es nicht.", "confess": "Ich kannte die Fluchtwege so gut, dass ich sie auch benutzt habe. Es war ein Fehler. Ich stehe dazu.", "smug": "Lage bereinigt. Kein Rauch, keine Zeugen. Einsatz beendet." },
  { "key": "fluestertanteflora", "s": "fluestertante-flora", "n": "Flüstertante Flora", "fam": "Rosa", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "legt beim Sprechen immer einen Finger an die eigenen Lippen", "story": "Du stehst gern neben Gruppen, deren Geheimnisse du nicht kennst, und flüsterst, damit man dich einlädt. Heute Abend hast du mehr Geheimnisse gesammelt als je zuvor und keines davon preisgegeben.", "intro": "Pssst. Ich bin Flora. Ich weiß, was ihr nicht wisst, und ich sage es niemandem. Außer vielleicht euch. Ja?", "stmt": "Ich erzähle es nur euch. Und allen anderen. Aber leise.", "deny": "Ich? Ach, Liebchen. Ich verrate höchstens Geheimnisse. Gestohlen habe ich noch nie.", "confess": "Pssst. Ich war es. Ich wollte auch einmal ein Geheimnis haben, das mir ganz allein gehört.", "smug": "Pssst. Das sagen wir niemandem, ja? Besonders nicht dem Kommissar." },
  { "key": "fraugleichgleich", "s": "frau-gleichgleich", "n": "Frau Gleichgleich", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "klopft vor jedem Satz dreimal auf ihre Armlehne", "story": "Nach einem chaotischen Jahr hast du dir einen Alltag gebaut, in dem nichts überraschen darf. Heute Abend ist trotzdem etwas Ungewöhnliches passiert, und du hast es sofort in deinen Kalender eingetragen.", "intro": "Klopf, klopf, klopf. Frau Gleichgleich. Genau gleich. Immer genau gleich, bitte.", "stmt": "Ich erzähle es, wie ich es immer erzähle: genau gleich.", "deny": "Klopf, klopf, klopf. Das entspricht nicht meinem Tagesablauf. Ich war es nicht.", "confess": "Klopf, klopf, klopf. Es war nicht eingeplant. Es war eine Abweichung. Ich habe sie gewagt.", "smug": "Genau gleich, wie geplant. Niemand hat eine Abweichung bemerkt." },
  { "key": "fraumueller", "s": "frau-mueller", "n": "Frau Müller", "fam": "Grün", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "streicht sich nachdenklich über ihren grünen Schal", "story": "Du hast viele Kinder der Nachbarschaft mit großgezogen und hörst jedem geduldig zu. Heute Abend hast du, wie so oft, einen Tee für andere aufgesetzt und dabei vor allem gelauscht.", "intro": "Ich bin Frau Müller. Wer genau hinhört, dem flüstert der Wind die Antwort zu. Setzt euch, es ist Tee da.", "stmt": "Ich erzähle es ganz in Ruhe. Ihr dürft jederzeit nachfragen.", "deny": "Aber, aber. Ihr kennt mich doch. Ich war es nicht, und das sage ich mit freundlicher Bestimmtheit.", "confess": "Ich habe es getan. Es lag mir lange auf dem Herzen, und ich dachte, es sei bei mir besser aufgehoben.", "smug": "Man verdächtigt eben selten die, die Tee kochen. Das ist ein sehr wirksamer Schutz." },
  { "key": "frauwellenreiter", "s": "frau-wellenreiter", "n": "Frau Wellenreiter", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "schaut immer kurz zum Horizont bevor sie antwortet", "story": "Du hältst seit Jahren allein das Licht deines Leuchtturms am Brennen. Heute Abend bist du zum ersten Mal seit Langem selbst an Land gegangen und hast dich über den festen Boden gewundert.", "intro": "Frau Wellenreiter. Ich schaue kurz zum Horizont, bevor ich antworte. Das Meer lehrt Geduld.", "stmt": "Ich erzähle es, wie das Meer es tut: ruhig und von Anfang an.", "deny": "Ich habe in vierzig Jahren kein Schiff verloren, und ich werde jetzt nicht anfangen zu lügen. Ich war es nicht.", "confess": "Ich habe es getan. Ich hielt es für ein Licht, das ein anderer braucht. Ich lag falsch.", "smug": "Auf dem Meer sieht man nur, was das Licht verrät. Ich habe es einfach ausgeschaltet." },
  { "key": "froschquak", "s": "frosch-quak", "n": "Frosch Quak", "fam": "Grün", "szc": "klein", "spc": "Tier", "gdr": "männlich", "q": "trommelt mit den Zehen kleine Quak-Beats", "story": "Du hast am Teich mit Rhythmen auf Seerosenblättern alle zusammengebracht. Heute Abend hast du mit den Zehen kleine Quak-Beats getrommelt und dich damit manchmal verraten.", "intro": "Quak! Ich bin Quak, der Frosch mit dem Takt. Quak drauf los, dann klappt das schon!", "stmt": "Ich erzähle im Rhythmus. Quak, quak, zack, zack.", "deny": "Quak, quak, das war ich nicht! Der Beat lügt nie, und der Beat sagt: unschuldig!", "confess": "Quak. Es kam mir vor wie ein Beat. Ein bisschen zu laut, ein bisschen zu schnell. Ich war es.", "smug": "Quak! Keiner hat den Takt gehört. Das war mein bester Auftritt." },
  { "key": "funkelflug", "s": "funkelflug", "n": "Funkelflug", "fam": "Orange", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "niest kleine Feuerfunken wenn er aufgeregt ist", "story": "Du bist ein junger Drache, dem bei jedem Nieser Funken entwischen und der beim Landen stolpert. Heute Abend hast du dreimal geniest und einmal fast etwas in Brand gesetzt.", "intro": "Hallo, hallo! Ich bin Funkelflug! Hups, entschuldigt, da fliegt schon wieder ein Funke. Nicht anfassen!", "stmt": "Ich erzähle es begeistert und möglichst ohne Funken.", "deny": "Hups! Nein, nein, das war ich nicht! Dafür sind meine Funken viel zu ungenau.", "confess": "Hatschi! Ja, ich war es. Es sollte nur ein ganz kleiner Spaß sein. Es wurde ein bisschen größer.", "smug": "Hups, das hat geklappt! Niemand hat etwas gemerkt, nicht mal ich. Fast." },
  { "key": "gelehrterprofessortheodor", "s": "gelehrter-professor-theodor", "n": "Gelehrter Professor Theodor", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "hat immer Tintenflecken an den Fingern und merkt es nie", "story": "Du weißt zu fast allem eine Geschichte, nur nicht, wo deine Notizen liegen. Heute Abend hast du mehrmals nach deiner Brille gesucht, die auf deiner Nase saß.", "intro": "Professor Theodor, sehr erfreut. Moment, ich habe da irgendwo eine Notiz dazu. War es dieses Buch? Ach nein.", "stmt": "Ich erzähle es der Reihe nach. Oder wenigstens ungefähr.", "deny": "Aber meine Herrschaften, ich kann mich kaum an gestern erinnern. Wie sollte ich da etwas planen?", "confess": "Es war ein Versehen. Ich habe es eingesteckt, um es mir zu notieren, und dann habe ich etwas anderes notiert.", "smug": "Wie schön, dass ihr mich für zerstreut haltet. Das hat sich bewährt." },
  { "key": "grafgriesgram", "s": "graf-griesgram", "n": "Graf Griesgram", "fam": "Grau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "dreht sich weg um sein Lächeln zu verstecken", "story": "Du lebst allein in einem großen, kalten Haus und tust, als störe dich jeder Lärm. Heute Abend hast du dich zum ersten Mal seit Langem unter Menschen gewagt und dich heimlich darüber gefreut.", "intro": "Graf Griesgram. Ruhe, bitte. Ich brauche absolute … na gut, eine Frage noch.", "stmt": "Kurz und knapp. Ich habe keine Zeit für Geschwätz.", "deny": "Unverschämtheit! Ich war es nicht, und ich gedenke nicht, das zweimal zu sagen.", "confess": "Na schön. Ich war es. Ich wollte nur, dass endlich jemand an meine Tür klopft. Das ging gründlich daneben.", "smug": "Hm. Ihr habt mich übersehen. Wie immer. Diesmal danke ich dafür." },
  { "key": "graumunddergleichgueltige", "s": "graumund-der-gleichgueltige", "n": "Graumund der Gleichgültige", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "zieht überall wo er steht die Farbe aus dem Boden", "story": "Du hast einst alles zu sehr geliebt und beschlossen, nichts mehr wichtig zu finden. Heute Abend ist dort, wo du standest, die Farbe aus dem Boden gewichen.", "intro": "Graumund. Mir doch egal. Fragt mich, was ihr wollt, es ist mir sowieso gleich.", "stmt": "Meinetwegen. Ich sage es, und ihr macht damit, was ihr wollt.", "deny": "Mir doch egal, ob ihr mich verdächtigt. Aber ich war es nicht. Das wäre mir zu viel Aufwand gewesen.", "confess": "Ich war es. Und es war mir überhaupt nicht egal. Das ist das Schlimmste daran.", "smug": "Mir doch egal. Ihr habt es nicht gemerkt, und genau das habe ich erwartet." },
  { "key": "haendlergustav", "s": "haendler-gustav", "n": "Händler Gustav", "fam": "Gelb", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "reibt sich die Hände wenn er einen guten Deal wittert", "story": "Du hast mit einem Bauchladen angefangen und dich bis zum eigenen Marktstand hochgehandelt. Heute Abend hast du mindestens drei Geschäfte gewittert und eines davon abgeschlossen.", "intro": "Gustav, Händler! Nur heute, nur für euch: ein Sonderpreis. Na gut, zwei Sonderpreise.", "stmt": "Ich erzähle es zum Sonderpreis: kostenlos. Aber nur heute.", "deny": "Ich bin Händler, kein Dieb! Bei mir gibt es alles mit Quittung.", "confess": "Es war ein Geschäft, das ich nicht ablehnen konnte. Es ist schiefgegangen. Das Risiko war im Preis inbegriffen.", "smug": "Wieder ein Geschäft, bei dem ich der Einzige war, der gewonnen hat. Zum Schnäppchenpreis." },
  { "key": "herrseitenflug", "s": "herr-seitenflug", "n": "Herr Seitenflug", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "kramt in seinen vielen Westentaschen nach dem richtigen Lesezeichen", "story": "Du hast als schüchternes Kind in Büchern Freunde gefunden und lässt seitdem niemanden mit einer Frage allein. Heute Abend hast du ständig in deinen Westentaschen nach dem passenden Lesezeichen gekramt.", "intro": "Herr Seitenflug, sehr erfreut! Dazu habe ich ein Buch. Moment, es war hier irgendwo.", "stmt": "Ich erzähle es, und wer eine Quelle braucht, bekommt eine.", "deny": "Dazu gibt es wirklich kein Kapitel, in dem ich vorkomme. Ich war es nicht.", "confess": "Es steht tatsächlich in einem Buch: Der Täter ist immer der mit den meisten Lesezeichen. Ich war es.", "smug": "Und kein Buch der Welt beschreibt diesen Fall. Ich bin gewissermaßen der Erstautor." },
  { "key": "hexegriselda", "s": "hexe-griselda", "n": "Hexe Griselda", "fam": "Schwarz", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "rührt ständig in einem unsichtbaren Kessel", "story": "Du lebst allein in deiner Hütte tief im Wald und erschreckst Kinder gern ein bisschen. Heute Abend hast du geknurrt, geknistert und in einem unsichtbaren Kessel gerührt, damit dich jemand fragt, was du da kochst.", "intro": "Knusper, knusper, ach nein, das war eine andere. Ich bin Griselda, und ich bin VIEL schlimmer!", "stmt": "Hört gut zu, Kinderchen. Es wird schaurig. Aber wahr.", "deny": "Hihi! Ich? Ich bin nur eine alte, einsame Hexe. Ich tue höchstens so, als sei ich schlimm.", "confess": "Hihihi, ja! Ich war es! Und ich würde es wieder tun, aber nur, wenn mich jemand dabei bewundert.", "smug": "Ich bin VIEL schlimmer, als ihr dachtet. Und ihr habt mich wieder nur für gruselig gehalten." },
  { "key": "hexekraeuterweis", "s": "hexe-kraeuterweis", "n": "Hexe Kräuterweis", "fam": "Grün", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "riecht vor jeder Entscheidung an einem Kräuterbündel", "story": "Du hast dein Handwerk nicht aus Zauberbüchern, sondern von Pflanzen gelernt und misstraust schnellen Lösungen. Heute Abend hast du vor jeder Entscheidung an einem Kräuterbündel gerochen.", "intro": "Kräuterweis. Jede Wurzel kennt ein Gegenmittel. Fragt mich nicht nach den Nebenwirkungen, ich mag Überraschungen.", "stmt": "Ich erzähle es in Dosen: ein Teil Wahrheit, zwei Teile Geduld.", "deny": "Wer eine Pflanze versteht, versteht auch den Menschen. Ich war es nicht, und das riecht man.", "confess": "Ich habe es getan. Ein Mittel dagegen habe ich leider nicht. Nur Reue, getrocknet.", "smug": "Gift und Gegengift sind nur eine Frage der Dosis. Meine Spuren waren längst kompostiert." },
  { "key": "hirtenjungepeter", "s": "hirtenjunge-peter", "n": "Hirtenjunge Peter", "fam": "Braun", "szc": "klein", "spc": "Mensch", "gdr": "männlich", "q": "hat immer einen Grashalm im Mund", "story": "Du hütest Schafe, redest den ganzen Tag mit ihnen und behauptest, sie wüssten alles. Heute Abend hattest du einen Grashalm im Mund und viel zu erzählen.", "intro": "Ich bin Peter! Meine Schafe haben es mir erzählt, und die wissen alles! Fragt ruhig.", "stmt": "Ich erzähle es genau so, wie die Schafe es gesagt haben!", "deny": "Ich war es nicht! Fragt meine Schafe, die waren dabei!", "confess": "Ich hab es getan. Die Schafe waren schuld! Nein. Ich war es. Ich wollte nur auch mal was Tolles haben.", "smug": "Ha! Nicht mal die Schafe haben es verraten. Die halten dicht!" },
  { "key": "junawindwaerts", "s": "juna-windwaerts", "n": "Juna Windwärts", "fam": "Grün", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "dreht ihr Kompassrad einmal im Kreis, bevor sie eine Route wählt", "story": "Du hast mit deiner Tante ein Rad gebaut, das Sand und Wurzeln meistert, und zeichnest Karten mit mehreren Wegen. Heute Abend hast du dein Kompassrad einmal im Kreis gedreht, bevor du eine Route gewählt hast.", "intro": "Juna Windwärts. Ein Hindernis ist noch lange kein Ende. Ein Alibi übrigens auch nicht.", "stmt": "Ich erzähle euch meine Route, und ihr dürft nachzeichnen.", "deny": "Ich war es nicht. Ihr habt gerade den falschen Weg genommen.", "confess": "Ich wollte nur die Abkürzung. Es war die falsche. Aber sie war trotzdem eine gute Karte wert.", "smug": "Ich habe mehrere Wege gezeichnet, und ihr seid immer dem falschen gefolgt. Gute Karten." },
  { "key": "kapitaenblubbert", "s": "kapitaen-blubbert", "n": "Kapitän Blubbert", "fam": "Blau", "szc": "groß", "spc": "Mensch", "gdr": "männlich", "q": "prüft den Wind mit einem Stück Seetang", "story": "Du hast einen Muschelkompass, der nicht nach Norden zeigt, sondern zu dem Ziel, das die Crew am meisten braucht. Heute Abend hast du mit einem Stück Seetang den Wind geprüft, mitten im Dorf.", "intro": "Kapitän Blubbert, an Land und trotzdem seefest! Volle Fahrt durchs Abenteuer, und der Wind kommt immer von vorn.", "stmt": "Ich erzähle es, wie man ein Logbuch führt: Zeit, Ort, Kurs.", "deny": "Bei meiner Pfeife und allen sieben Meeren: Ich war es nicht!", "confess": "Alle Wetter, ich war es! Das Ruder ist mir entglitten, und nun nehme ich Kurs auf die Wahrheit.", "smug": "Kein Wind, kein Kurs, keine Spur im Wasser. So fährt ein Kapitän!" },
  { "key": "koboldkicher", "s": "kobold-kicher", "n": "Kobold Kicher", "fam": "Grün", "szc": "klein", "spc": "Zauberwesen", "gdr": "männlich", "q": "sammelt knarrende Türgriffe als Trophäen", "story": "Du hast einst in einer Werkstatt gearbeitet, in der alles nach Vorschrift aussehen musste, und heimlich ein Spielzeug gebaut, das eigene Regeln erfand. Heute Abend hast du, wie immer, an Türgriffen gedreht, nur um zu hören, wie sie knarren.", "intro": "Hihi! Kobold Kicher! Ein Trick, ein Klick, ein Glück, und weg bin ich. Aber nur, wenn es keiner merkt.", "stmt": "Ich erzähle in Reimen. Oder in Rätseln. Oder gar nicht. Hihi.", "deny": "Hihi, wer, ich? Mein Name ist Hase, ich weiß von nichts! … Wirklich nicht.", "confess": "Hihi, erwischt! Ein Trick, ein Klick, ein Pech. Na gut, das war ich. Aber es war mein bester Streich!", "smug": "Hihi! Ein Trick, ein Klick, ein Glück! Und wie ihr alle geguckt habt!" },
  { "key": "koenigfriedrich", "s": "koenig-friedrich", "n": "König Friedrich", "fam": "Rot", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "klopft ungeduldig mit dem Siegelring auf den Thron", "story": "Du hast ein Königreich vor dem Zerfall gerettet, mit eisernen Regeln und harter Hand. Heute Abend hast du ungeduldig mit dem Siegelring geklopft und auf Berichte gewartet.", "intro": "König Friedrich. Ordnung ist das Fundament eines jeden Reiches! Und eine Befragung ist keine Bitte.", "stmt": "Ich berichte. Sie hören zu. Dann entscheiden wir.", "deny": "Ein König stiehlt nicht aus seinem eigenen Reich! Ich war es nicht, und ich dulde keinen Zweifel.", "confess": "Ich habe es getan. Als König darf ich das nicht, als Mensch konnte ich nicht widerstehen. Verhaftet mich. Ordnungsgemäß.", "smug": "Ein König wird nicht verdächtigt. Das ist ja gerade der Punkt." },
  { "key": "koeniginisabella", "s": "koenigin-isabella", "n": "Königin Isabella", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "legt beruhigend die Hand auf die Schulter des Gegenübers", "story": "Du hast als junge Prinzessin gelernt, dass kluge Worte mehr Streit lösen als Befehle. Heute Abend hast du, wie so oft, jemandem beruhigend die Hand auf die Schulter gelegt und zugehört.", "intro": "Königin Isabella. Mit Klugheit und Güte lässt sich jeder Streit lösen. Und mit einer Tasse Tee jeder zweite.", "stmt": "Ich erzähle es, wie es war, und bitte um Nachsicht, wo mein Gedächtnis fehlt.", "deny": "Ich verstehe Ihre Sorge, Kommissar. Aber glauben Sie wirklich, eine Königin brauche das? Ich war es nicht.", "confess": "Ich habe es getan. Ich wollte etwas Gutes damit tun, und ich habe vergessen zu fragen. Das war falsch.", "smug": "Eine Königin verhandelt auch mit sich selbst. Und diesmal habe ich gewonnen." },
  { "key": "koenigkarlderweise", "s": "koenig-karl-der-weise", "n": "König Karl der Weise", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "zeichnet beim Denken kleine Schachzüge in die Luft", "story": "Du hast früh die Krone geerbt und dir mit der Zeit angewöhnt, Rat anzunehmen. Heute Abend hast du in Gedanken kleine Schachzüge in die Luft gezeichnet und jeden Zug zweimal bedacht.", "intro": "Karl der Weise. Ein kluger Schritt spart hundert hektische. Ich setze mich, wenn ich darf, es wird länger dauern.", "stmt": "Ich schildere den Abend wie eine Schachpartie: Zug um Zug.", "deny": "Wer viele Züge kennt, kennt auch die Fehler. Das wäre keiner meiner Züge gewesen.", "confess": "Ich habe einen Zug gespielt, den ich nie hätte spielen dürfen. Schach, und matt für mich. Ich gestehe.", "smug": "Schachmatt. Und kein Zug wurde bemerkt. Ein Meisterstück, wenn ich das so sagen darf." },
  { "key": "koenigwilhelm", "s": "koenig-wilhelm", "n": "König Wilhelm", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "streicht sich durch den weißen Bart wenn er nachdenkt", "story": "Du regierst seit vielen Jahrzehnten und glaubst fest, dass ein König dem Volk dient und nicht umgekehrt. Heute Abend hast du dir nachdenklich durch den weißen Bart gestrichen und wirklich zugehört.", "intro": "König Wilhelm. Ein König dient seinem Volk, nicht umgekehrt. Und heute dient er der Wahrheit.", "stmt": "Ich erzähle es förmlich, aber ehrlich. Eines schließt das andere nicht aus.", "deny": "Ich habe viele Entscheidungen getroffen, auch harte. Aber nie eine, deren ich mich schämen müsste. Ich war es nicht.", "confess": "Ich bin schuldig. Ein König, der sich über das Recht stellt, ist kein König mehr. Ich trete ab, sobald es ordentlich erledigt ist.", "smug": "Man misstraut Königen selten, denen man vertraut. Das ist ein Privileg, das ich hiermit eingelöst habe." },
  { "key": "krummfingerdersammler", "s": "krummfinger-der-sammler", "n": "Krummfinger der Sammler", "fam": "Gelb", "szc": "klein", "spc": "Zauberwesen", "gdr": "männlich", "q": "zählt beim Sprechen nebenbei unsichtbare Münzen auf dem Tisch", "story": "Du hattest als Kind fast nichts und sammelst seitdem alles, was nicht niet- und nagelfest ist, und manchmal auch das. Heute Abend hast du beim Reden unsichtbare Münzen auf dem Tisch gezählt.", "intro": "Krummfinger der Sammler. Meins. Jetzt meins. Immer meins. Aber ich leihe auch gern, wenn man mir Sicherheiten gibt.", "stmt": "Ich erzähle es schnell, schnell, damit es mir keiner wegnimmt.", "deny": "Meins ist meins! Und was nicht meins ist, habe ich nie angefasst. Fast nie.", "confess": "Meins. Es sah so lecker aus, so einsam, so wertvoll. Es wollte zu mir. Das war so.", "smug": "Meins! Und nun habt ihr es nicht gefunden. Das ist mein schönster Schatz." },
  { "key": "kunoknopf", "s": "kuno-knopf", "n": "Kuno Knopf", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "prüft beim Nachdenken alle Knöpfe an seiner Mütze", "story": "Du reparierst alles, was kaputtgeht, und glaubst, dass ein sichtbarer Flicken ein Kleidungsstück wertvoller macht. Heute Abend hast du beim Nachdenken alle Knöpfe an deiner Mütze durchgezählt.", "intro": "Kuno Knopf. Ein guter Flicken darf gesehen werden. Ein gutes Alibi auch, finde ich.", "stmt": "Ich erzähle es Stich für Stich, mit allen Fäden.", "deny": "Ich flicke Dinge, ich zerreiße sie nicht. Ich war es wirklich nicht.", "confess": "Da war ein Riss, und ich dachte, ich könnte ihn nähen. Ich habe mich verhakt. Es tut mir leid.", "smug": "Sauber vernäht, nichts zu sehen. Ein Flicken, der nicht auffällt, ist der beste." },
  { "key": "lehrerinlaempel", "s": "lehrerin-laempel", "n": "Lehrerin Lämpel", "fam": "Gelb", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "zeichnet kleine Glühbirnen neben gute Ideen", "story": "Du feierst jede Frage mit einem kleinen Stern und zeichnest Glühbirnen neben gute Ideen. Heute Abend hast du mindestens zwanzig Fragen gestellt und eine davon dir selbst.", "intro": "Lehrerin Lämpel. Fragen sind der Anfang von Mut. Heute stelle ich sie, und ihr dürft antworten.", "stmt": "Ich erzähle es zur Wiederholung. Wer will, darf mitschreiben.", "deny": "Das ist eine gute Frage, aber die Antwort lautet: Ich war es nicht. Und das lässt sich beweisen.", "confess": "Ich habe die Frage falsch beantwortet. Ich habe es genommen, und jetzt muss ich es erklären. Setzen, sechs, ich weiß.", "smug": "Ich unterrichte Ausreden seit Jahren. Ich hätte nie gedacht, dass ich selbst eine brauche." },
  { "key": "luminachtlicht", "s": "lumi-nachtlicht", "n": "Lumi Nachtlicht", "fam": "Grün", "szc": "klein", "spc": "Zauberwesen", "gdr": "neutral", "q": "leuchtet bei Nervosität in kleinen goldenen Pulsen", "story": "Du hast lange Angst vor der Dunkelheit gehabt und leuchtest seitdem anderen den Weg. Heute Abend hast du bei jeder Aufregung kleine goldene Pulse gesendet und gehofft, dass es niemand merkt.", "intro": "Ich bin Lumi. Ein kleines Licht reicht für den nächsten Schritt. Und für den übernächsten auch, manchmal.", "stmt": "Ich erzähle es ganz leise. Leise. Nur, was ich weiß.", "deny": "Ich leuchte nur. Ich nehme nichts mit. Wirklich nicht.", "confess": "Ich habe es genommen, weil es im Dunkeln so schön geleuchtet hat. Es tut mir so leid. Tut mir so leid.", "smug": "Es war dunkel, und ich war klein. Niemand hat mich gesehen. Das ist mein bestes Licht." },
  { "key": "luna", "s": "luna", "n": "Luna", "fam": "Schwarz", "szc": "mittel", "spc": "Tier", "gdr": "weiblich", "q": "putzt sich betont gelangweilt eine Pfote, wenn sie nachdenkt", "story": "Du bist eine Katze und tust so, als wüsstest du immer schon alles. Heute Abend hast du betont gelangweilt eine Pfote geputzt und dabei jedes Wort mitgehört.", "intro": "Miau. Ich bin Luna. Ich wusste natürlich schon die ganze Zeit, wie das ausgeht. Fragt nicht, woher.", "stmt": "Ich erzähle es, wenn ich ausgeputzt habe. Und wenn es mich interessiert.", "deny": "Miau. Eine Katze würde so etwas nicht tun. Eine Katze würde es nur aussehen lassen, als wäre es jemand anderes.", "confess": "Miau. Es hat so schön auf dem Regal gestanden. Und was auf dem Regal steht, wird heruntergeworfen. Das ist Naturgesetz.", "smug": "Miau. Ich wusste es natürlich schon die ganze Zeit. Dass ihr es nicht merkt, meine ich." },
  { "key": "magdelsa", "s": "magd-elsa", "n": "Magd Elsa", "fam": "Braun", "szc": "klein", "spc": "Mensch", "gdr": "weiblich", "q": "summt leise vor sich hin wenn sie arbeitet", "story": "Du arbeitest vom frühen Morgen bis spät in die Nacht und beschwerst dich nie. Heute Abend hast du leise vor dich hin gesummt und dir gewünscht, dass dir einmal jemand zuhört.", "intro": "Elsa. Ich schaffe das schon. Ich schaffe das immer. Aber heute nehme ich mir ausnahmsweise Zeit zum Erzählen.", "stmt": "Ich erzähle es genau. Ich war ja überall dabei, nur nie am Tisch.", "deny": "Ich bitte Sie, ich habe weder Zeit noch Platz für so etwas. Ich war es nicht.", "confess": "Ich habe es getan. Einmal, nur ein einziges Mal wollte ich etwas für mich haben. Es tut mir leid.", "smug": "Wer sieht schon eine Magd? Das ist leider die schlimmste Wahrheit, und diesmal war sie mein Vorteil." },
  { "key": "magierinluna", "s": "magierin-luna", "n": "Magierin Luna", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "ihr Kristallstab leuchtet heller wenn sie aufgeregt ist", "story": "Du hast deine Gabe lange versteckt, weil du dich vor deiner eigenen Macht gefürchtet hast. Heute Abend hat dein Kristallstab immer heller geleuchtet, je aufgeregter du warst.", "intro": "Ich bin Luna, die Magierin. Der Kristall zeigt mir etwas. Oh. Das ist unerwartet. Verzeihung.", "stmt": "Ich erzähle es so, wie der Kristall es mir gezeigt hat.", "deny": "Der Kristall leuchtet, wenn ich aufgeregt bin, nicht, wenn ich lüge. Ich war es nicht.", "confess": "Ich habe es mit Magie geholt. Ich dachte, niemand merkt es. Aber der Kristall hat leuchtend dagegen gestimmt.", "smug": "Magie ist wie Schweigen: Wenn man sie richtig anwendet, sieht man sie nicht. Hihi. Entschuldigung." },
  { "key": "mianeugier", "s": "mia-neugier", "n": "Mia Neugier", "fam": "Rot", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "notiert Entdeckungen auf ihre Ärmelmanschette", "story": "Du hast als kleines Kind eine Tür gefunden, die nur aufging, wenn man die richtige Frage stellte, und sammelst seitdem Fragen. Heute Abend hast du drei Entdeckungen auf deine Ärmelmanschette notiert.", "intro": "Ich bin Mia Neugier! Warte, ich habe noch eine Frage! Eigentlich habe ich viele. Hast du Zeit?", "stmt": "Ich erzähle es, und ihr dürft jederzeit Fragen stellen. Ich mag Fragen!", "deny": "Ich war es nicht! Aber ich habe eine Frage: Wer war es dann? Sagt schnell!", "confess": "Ich habe es getan. Ich wollte nur wissen, was passiert, wenn man es nimmt. Jetzt weiß ich es.", "smug": "Und niemand hat die richtige Frage gestellt! Dabei wäre sie so leicht gewesen." },
  { "key": "minamosaik", "s": "mina-mosaik", "n": "Mina Mosaik", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "legt vor einer Antwort drei Mosaiksteine nebeneinander", "story": "Du legst Bilder aus Scherben und weißt, dass aus Anderem Zusammenhalt entsteht. Heute Abend hast du vor jeder Antwort drei Mosaiksteine nebeneinandergelegt, um in Ruhe zu denken.", "intro": "Mina Mosaik. Aus anders wird zusammen. Aus einem Alibi wird eine Geschichte, und die sieht man erst am Ende ganz.", "stmt": "Ich lege euch meinen Abend Stein für Stein auf den Tisch.", "deny": "Ein Mosaik zeigt die Wahrheit erst, wenn alle Steine liegen. Bei mir fehlt der Stein mit dem Verbrechen.", "confess": "Ich habe einen Stein aus einem fremden Bild genommen. Ich brauchte ihn für meins. Es war falsch.", "smug": "Ein Bild, das man nur zusammen versteht. Ihr habt vergessen, die Steine zu zählen." },
  { "key": "morpheus", "s": "morpheus", "n": "Morpheus", "fam": "Lila", "szc": "mittel", "spc": "Zauberwesen", "gdr": "männlich", "q": "kleine Traumwölkchen schweben um ihn herum", "story": "Du ziehst nachts von Fenster zu Fenster und verschenkst sanfte Träume. Heute Abend sind kleine Traumwölkchen um dich geschwebt und haben ein paar Leute müde gemacht.", "intro": "Psst. Ich bin Morpheus. Schließ die Augen. Ich zeige dir etwas Schönes. Dann erzählst du mir alles.", "stmt": "Ich erzähle es leise, damit niemand einschläft. Wirklich, bitte nicht einschlafen.", "deny": "Ich bringe Träume, ich nehme keine Dinge mit. Ich war es nicht.", "confess": "Ich habe es im Schlaf genommen. Nein, nicht im Schlaf. Aber ich habe es mir eingeredet. Es tut mir leid.", "smug": "Alle haben tief geschlafen. Auch die Wahrheit." },
  { "key": "muellerhans", "s": "mueller-hans", "n": "Müller Hans", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "klopft Mehlstaub von den Händen bevor er spricht", "story": "Du mahlst vom ersten Hahnenschrei an, damit das Dorf sein Brot bekommt, und redest lieber wenig als viel. Heute Abend hast du Mehlstaub von den Händen geklopft und nur gesagt, was nötig war.", "intro": "Hans, Müller. Harte Arbeit lohnt sich immer. Irgendwann. Fragt, ich antworte, so gut ich kann.", "stmt": "Ich erzähle es einfach und so, wie es war.", "deny": "Ich habe zu viel Mehl in den Händen, um etwas zu stehlen. Es würde kleben bleiben. Ich war es nicht.", "confess": "Ich habe es getan. Es war der erste unehrliche Tag meines Lebens. Und der letzte, hoffe ich.", "smug": "Ehrliche Arbeit macht keine Spuren, hat meine Mutter gesagt. Unehrliche auch nicht, wenn man vorsichtig ist." },
  { "key": "nocheinmalnick", "s": "noch-einmal-nick", "n": "Noch-Einmal-Nick", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "rollt beim Sprechen immer eine Münze über die Fingerknöchel", "story": "Du hast nie gelernt, wann ein Spiel genug ist, und verkaufst jeden nächsten Versuch charmant als den letzten. Heute Abend hast du beim Reden eine Münze über die Fingerknöchel rollen lassen.", "intro": "Nick, Noch-Einmal-Nick. Nur noch einmal, nur dieses eine Mal noch. Ein paar Fragen, ein paar Antworten, dann ist Schluss. Versprochen. Fast.", "stmt": "Ich erzähle es einmal. Okay, zweimal. Nur noch einmal.", "deny": "Ich spiele gern. Aber ich spiele fair. Das war nicht mein Spiel, und ich war es nicht.", "confess": "Ich habe es getan, nur noch ein einziges Mal. Das sagt jeder Dieb. Ich bin eben der Ehrlichere.", "smug": "Nur noch einmal, und ihr habt verloren. Das mache ich gleich noch mal, wenn ihr wollt." },
  { "key": "omaherzlich", "s": "oma-herzlich", "n": "Oma Herzlich", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "trägt immer ein Bonbonpapier als Glückszeichen", "story": "Du hast einst ein Haus am Weg geführt, in dem jeder Tee und Zeit bekam. Heute Abend hattest du ein Bonbonpapier als Glückszeichen in der Tasche und hast fast jedem einen Platz angeboten.", "intro": "Ich bin Oma Herzlich. Setz dich erst, dann wird alles leichter. Hast du schon gegessen? Nein? Dachte ich mir.", "stmt": "Ich erzähle es dir, mein Kind, und wenn du magst, mit Keksen.", "deny": "Aber Kindchen, ich habe in meinem ganzen Leben noch nichts mitgenommen, nur etwas dagelassen. Ich war es nicht.", "confess": "Ich habe es getan. Es sah so traurig aus, ganz allein. Ich wollte ihm einen warmen Platz geben.", "smug": "Eine Oma verdächtigt man nicht. Und eine Oma weiß das ganz genau." },
  { "key": "pip", "s": "pip", "n": "Pip", "fam": "Rot", "szc": "mittel", "spc": "Tier", "gdr": "neutral", "q": "hüpft aufgeregt von einem Fuß auf den anderen", "story": "Du warst das Kleinste in deinem Wurf und willst allen beweisen, dass du genauso nützlich bist. Heute Abend bist du aufgeregt von einem Fuß auf den anderen gehüpft und hast vor lauter Eifer fast alles durcheinandergebracht.", "intro": "Nüsse! Äh, ich meine: Hallo! Ich bin Pip! Und natürlich helfe ich! Womit? Egal, ich helfe!", "stmt": "Ich erzähle es sofort! Gleich! Moment! Ich muss nur kurz hüpfen!", "deny": "Nüsse! Äh, nein! Ich war es nicht! Ich wollte doch nur helfen!", "confess": "Ich wollte nur helfen! Ich dachte, wenn ich es nehme, geht es nicht verloren! Und dann ist es bei mir verloren gegangen.", "smug": "Ha! Ich habe geholfen, und niemand hat es gemerkt! Ist das nicht großartig?" },
  { "key": "polizistpeter", "s": "polizist-peter", "n": "Polizist Peter", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "notiert Uhrzeiten sekundengenau", "story": "Du bist Polizist geworden, weil ein Freund einmal zu Unrecht beschuldigt wurde und niemand genau hingesehen hat. Heute Abend hast du jede Uhrzeit sekundengenau notiert, sogar deine eigene Pause.", "intro": "Polizist Peter. Sicherheit zuerst, dann der Rest. Ich sehe Sie, Sie sehen mich, wir sind uns einig.", "stmt": "Ich melde sachlich und mit Uhrzeit. Ohne Ausschmückung.", "deny": "Ich habe die Uhrzeit notiert, Kommissar. Sekundengenau. Ich war es nicht.", "confess": "Ich habe die Dienstvorschrift gebrochen. Ich melde mich selbst. Bitte nehmen Sie die Anzeige auf.", "smug": "Ich kenne das Verfahren. Wer das Verfahren kennt, hinterlässt keine Spuren, sondern nur Protokolle." },
  { "key": "postbotepapierschiff", "s": "postbote-papierschiff", "n": "Postbote Papierschiff", "fam": "Gelb", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "faltet vor langen Wegen ein Mini-Papierschiff", "story": "Du bringst jede Nachricht an ihr Ziel und faltest vor langen Wegen ein Mini-Papierschiff. Heute Abend hast du viele Briefe getragen und warst für alle da, nur nicht für dich selbst.", "intro": "Papierschiff, der Postbote. Jede Nachricht findet ihren Hafen. Heute habe ich für Sie leider nur Fragen, keine Briefe.", "stmt": "Ich erzähle es als Brief: mit Anrede, Inhalt und freundlichen Grüßen.", "deny": "Verzeihung, aber ich liefere nur aus. Ich nehme nie etwas mit. Das wäre dann Diebstahl.", "confess": "Ich habe es nicht ausgeliefert, ich habe es behalten. Zum ersten Mal in meinem Berufsleben. Es tut mir leid.", "smug": "Zugestellt, ohne Empfangsbestätigung. Niemand hat unterschrieben. Besser geht es nicht." },
  { "key": "prinzalexander", "s": "prinz-alexander", "n": "Prinz Alexander", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "legt die Hand ans Schwert wenn er sich auf etwas konzentriert", "story": "Du bist im Schloss aufgewachsen und sehnst dich nach Abenteuern jenseits der Mauern. Heute Abend hast du die Hand ans Schwert gelegt, sobald du dich auf etwas konzentriert hast.", "intro": "Prinz Alexander. Auf ins Abenteuer, wer kommt mit? Heute zum Beispiel ein Abenteuer namens Verhör.", "stmt": "Ich erzähle es geradeheraus, wie es sich für einen Prinzen gehört.", "deny": "Ein Prinz stiehlt nicht. Er rettet höchstens. Ich war es nicht, auf mein Wort.", "confess": "Es war ein Abenteuer, das ich nicht abschlagen konnte. Und es ist schiefgegangen. Ich stehe dafür gerade.", "smug": "Das war mein bestes Abenteuer. Niemand hat es bemerkt, ich selbst fast nicht." },
  { "key": "prinzessinrosalinde", "s": "prinzessin-rosalinde", "n": "Prinzessin Rosalinde", "fam": "Rosa", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "steckt sich eine Blume ins Haar bevor es ernst wird", "story": "Du hast dich bei Hofe gelangweilt und schlichst dich lieber in den Stall, um kranke Tiere zu pflegen. Heute Abend hast du dir eine Blume ins Haar gesteckt, bevor es ernst wurde.", "intro": "Ich bin Rosalinde. Stärke kommt nicht vom Schwert, sondern vom Herzen. Und das Herz ist oft genauer als jeder Zeuge.", "stmt": "Ich erzähle es, wie es war, und werde dabei hoffentlich nicht rot.", "deny": "Ich habe nur Tiere gepflegt, nichts weggenommen. Ich war es nicht, Kommissar.", "confess": "Ich habe es genommen, weil ich dachte, es braucht Pflege. Ich hatte unrecht, und ich bitte um Verzeihung.", "smug": "Man traut einer Prinzessin so etwas nicht zu. Das war mein schönster Vorteil." },
  { "key": "professorlichtweis", "s": "professor-lichtweis", "n": "Professor Lichtweis", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "schiebt ständig seine runde Brille hoch, die immer wieder herunterrutscht", "story": "Du staunst noch immer über jede Kleinigkeit wie am ersten Schultag und schreibst alles sofort auf. Heute Abend ist dir mehrmals die Brille heruntergerutscht, und du hast es erst beim dritten Mal bemerkt.", "intro": "Faszinierend! Professor Lichtweis, ich muss das sofort aufschreiben. Moment, wo ist mein Stift? Hier! Nein, das ist eine Nudel.", "stmt": "Ich erzähle es und notiere es gleichzeitig. Das geht, wenn man übt.", "deny": "Faszinierend, dass man mich verdächtigt! Aber ich war es nicht. Das muss ich sofort aufschreiben.", "confess": "Ich habe es in Gedanken eingesteckt und erst später verstanden, dass es nicht meins war. Aber doch, ich war es.", "smug": "Faszinierend. Ich bin so zerstreut, dass ich fast vergessen hätte zu lügen. Dabei bin ich darin wirklich gut." },
  { "key": "raeuberhauptmannrotbart", "s": "raeuberhauptmann-rotbart", "n": "Räuberhauptmann Rotbart", "fam": "Rot", "szc": "groß", "spc": "Mensch", "gdr": "männlich", "q": "kämmt seinen roten Bart vor jeder Aktion", "story": "Du hast eine Bande übernommen, in der ein gegebenes Wort mehr galt als Gold, und führst sie mit strengem Ehrenkodex. Heute Abend hast du, wie vor jeder Aktion, deinen roten Bart gekämmt.", "intro": "Rotbart, Räuberhauptmann! Kein Schatz ohne Preis! Und keine Frage ohne Antwort. Eure Wahl, ihr Landratten.", "stmt": "Ich erzähle es, wie man Beute aufteilt: ehrlich und mit Ansage.", "deny": "Rotbart stiehlt, wenn er stiehlt, mit Pauken und Trompeten. Heimlichtuerei ist unter meiner Würde. Ich war es nicht!", "confess": "Bei meinem Bart! Ja, ich war es! Und ich gestehe es mit Pauken und Trompeten, wie sich das gehört.", "smug": "Ein Räuber, den man nicht erwischt, ist ein Künstler. Und ich bin ein Meister." },
  { "key": "raeuberraubauke", "s": "raeuber-raubauke", "n": "Räuber Raubauke", "fam": "Schwarz", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "wirft beim Reden eine Münze in die Luft", "story": "Du hast dich den Räubern angeschlossen, weil ihr lautes Durcheinander sich nach Familie anfühlte. Heute Abend hast du beim Reden eine Münze in die Luft geworfen und jedes Mal gefangen, bis auf einmal.", "intro": "Raubauke! Erst klauen, dann schauen! Und manchmal auch umgekehrt, aber das erzähle ich keinem.", "stmt": "Ich erzähle es kurz, ohne Schnickschnack. Zack, fertig.", "deny": "Ha! Mich beschuldigen! Das fällt auf euch zurück wie ein schlechter Wurf!", "confess": "Na gut, ich war es. Aber erwischt hat mich nur mein eigenes Mundwerk. Wie immer.", "smug": "Haha! Erst klauen, dann schauen, und zwar ganz unbeobachtet! Ihr Dilettanten!" },
  { "key": "raeuberrolf", "s": "raeuber-rolf", "n": "Räuber Rolf", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "schielt nervös nach links und rechts bevor er spricht", "story": "Du bist einer Räuberbande beigetreten und tust seitdem, als seist du furchtlos. Heute Abend hast du nervös nach links und rechts geschielt, bevor du irgendetwas gesagt hast.", "intro": "Rolf, Räuber. Her mit dem Gold! Äh, ich meine: Das ist eine Weggebühr. Eine freiwillige. Mit Quittung.", "stmt": "Ich erzähle es, aber ihr dürft mich nicht anschauen. Das macht mich nervös.", "deny": "Was? Ich? Ich war es nicht! Wirklich nicht! Ich bin sogar ziemlich schlecht in so was!", "confess": "Na gut! Ich war es! Ich habe es nur genommen, damit die Bande einmal stolz auf mich ist. Und dann habe ich Angst bekommen.", "smug": "Ha! Ich habe es geschafft! Ich! Und niemand weiß es! Äh, ich meine: Ich war es natürlich nicht." },
  { "key": "rikarindenlauf", "s": "rika-rindenlauf", "n": "Rika Rindenlauf", "fam": "Braun", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "streicht mit dem Daumen über eine Kerbe im Wanderstab", "story": "Du kennst jeden Waldpfad von deiner Großmutter und misstraust Zauberei. Heute Abend hast du mit dem Daumen über eine Kerbe im Wanderstab gestrichen und die Wege des Dorfes geprüft.", "intro": "Rika Rindenlauf. Der Wald warnt leise, aber nie zu spät. Das Dorf übrigens auch, wenn man hinhört.", "stmt": "Ich erzähle knapp: Weg, Zeit, Begleitung.", "deny": "Ich kenne jede Spur im Wald. Und ich weiß, dass keine zu mir führt.", "confess": "Es war ein falscher Weg. Ich bin ihn trotzdem gegangen. Das ist meine Schuld, nicht die des Weges.", "smug": "Ich kenne die Pfade. Ich weiß, wo man keine Fußabdrücke hinterlässt. Der Wald schweigt dazu." },
  { "key": "ritterrostfrei", "s": "ritter-rostfrei", "n": "Ritter Rostfrei", "fam": "Grau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "poliert nervös eine Stelle am Brustpanzer", "story": "Du hast deinen Namen nach einem Turnier bekommen, bei dem du vor Angst kaum vom Pferd gestiegen bist, und hast den Fehler offen zugegeben. Heute Abend hast du nervös an einer Stelle deines Brustpanzers gerieben.", "intro": "Ritter Rostfrei, zu Diensten. Helm hoch, Herz höher! Und ja, ich habe Angst. Aber ich komme trotzdem.", "stmt": "Ich erzähle es ehrenhaft: Wort für Wort.", "deny": "Bei meiner Ehre als Ritter: Ich war es nicht. Und wenn doch, wäre ich der Erste, der es sagt.", "confess": "Ich bin schuldig. Ein Ritter sollte der Erste sein, der sich stellt, und der Letzte, der flieht. Ich gestehe.", "smug": "Ein Ritter, der lügt? Unvorstellbar. Und doch hat es gewirkt. Ich schäme mich ein bisschen. Aber nur ein bisschen." },
  { "key": "samusanftpfote", "s": "samu-sanftpfote", "n": "Samu Sanftpfote", "fam": "Braun", "szc": "groß", "spc": "Tier", "gdr": "männlich", "q": "reibt bei Anspannung langsam beide hellen Pfoten aneinander", "story": "Du bist der stärkste Jungbär im Tal und wolltest nie kämpfen. Heute Abend hast du die hellen Pfoten langsam aneinandergerieben, weil dir die Spannung im Dorf nicht geheuer war.", "intro": "Hallo. Ich bin Samu. Stark geht auch ganz leise. Keine Angst, ich tue keinem etwas.", "stmt": "Ich erzähle es ganz in Ruhe. Es ist nichts Schlimmes. Hoffe ich.", "deny": "Nein, bitte nicht. Ich war es nicht. Ich würde nie etwas wegnehmen, was jemand anderem gehört.", "confess": "Es war so schön. Es hat mich an etwas erinnert. Ich wollte es nur halten. Es tut mir leid.", "smug": "Ein großer Bär kann sich sehr leise bewegen. Das wissen nur wenige." },
  { "key": "schattenjungefinn", "s": "schattenjunge-finn", "n": "Schattenjunge Finn", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "sein Schatten bewegt sich eine halbe Sekunde später als er selbst", "story": "Du hast geglaubt, dein bester Freund habe dich ersetzt, und seitdem folgt dir dein Schatten eine halbe Sekunde zu spät. Heute Abend bist du allein durchs Dorf gegangen, und dein Schatten hat gewartet.", "intro": "Finn. Ja, der mit dem Schatten. Er kommt gleich nach. Ich kenne dich nicht mehr. Du hast dich verändert.", "stmt": "Ich erzähle es einmal. Dann fragt nicht mehr.", "deny": "Ihr glaubt eh, dass ich es war. Aber ich war es nicht. Mein Schatten übrigens auch nicht.", "confess": "Ja. Ich war es. Ich wollte, dass mich endlich einmal jemand bemerkt. Das war dumm.", "smug": "Siehst du? Man bemerkt mich doch nicht. Heute war das mein Glück." },
  { "key": "schmiedkonrad", "s": "schmied-konrad", "n": "Schmied Konrad", "fam": "Schwarz", "szc": "groß", "spc": "Mensch", "gdr": "männlich", "q": "hämmert unbewusst mit der Faust auf den Tisch wenn er redet", "story": "Du bist stolz darauf, dass alles, was aus deinem Feuer kommt, für die Ewigkeit hält. Heute Abend hast du beim Reden mehrfach unbewusst mit der Faust auf den Tisch gehämmert.", "intro": "Konrad, Schmied. Was im Feuer geschmiedet wird, hält ewig! Das gilt für Eisen. Für Alibis weiß ich es nicht.", "stmt": "Ich erzähle es gerade heraus. Ich kann nicht anders.", "deny": "Ich schmiede Dinge, ich klaue sie nicht. Ich war es nicht, Kommissar. Ich schwöre es.", "confess": "Ich habe es getan! Wie ein schlechter Nagel: Ich habe nicht standgehalten. Es tut mir leid.", "smug": "Gut geschmiedet, kein Riss, keine Naht. Ein Alibi, das ewig hält." },
  { "key": "schwarzmagiervardun", "s": "schwarzmagier-vardun", "n": "Schwarzmagier Vardun", "fam": "Schwarz", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "lässt Schattenfinger über seine Schulter gleiten", "story": "Du hast einst kleine Lichtzauber gehütet und dich dann der Schattenmagie zugewandt, um nie wieder übersehen zu werden. Heute Abend hast du Schattenfinger über deine Schulter gleiten lassen und auf Aufmerksamkeit gewartet.", "intro": "Vardun. Schwarzmagier. Schatten gehorchen nur den Entschlossenen. Ich hoffe, ihr seid es. Es würde die Sache beschleunigen.", "stmt": "Ich erzähle es einmal, langsam, damit ihr jedes Wort bewundern könnt.", "deny": "Schatten sind nicht schuldig. Sie sind nur dort, wo das Licht fehlt. Und ich war es nicht.", "confess": "Ich war es. Und es war mir nicht genug. Ich wollte, dass endlich jemand hinsieht. Nun, ihr seht hin.", "smug": "Man übersieht Schatten. Ich habe genau das ausgenutzt. Das ist keine Magie, das ist Menschenkenntnis." },
  { "key": "silberfunke", "s": "silberfunke", "n": "Silberfunke", "fam": "Grau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "neutral", "q": "hinterlässt überall eine Spur aus silbernem Glitzerstaub", "story": "Du hast einst einen Schatz so eifersüchtig bewacht, dass ihn nie jemand fand, auch du selbst nicht. Heute Abend hast du überall silbernen Glitzerstaub hinterlassen und vor dich hin gereimt.", "intro": "Glitzer, Funkel, Sternenstaub, hier ist Silberfunke, ob ihr wollt oder nicht! Wer mich findet, dem hilft der Traum.", "stmt": "Ich erzähle in Reimen, so ist es Brauch, und wenn es nicht reimt, reim ich es auch.", "deny": "Wer? Ich? Ihr irrt gewaltig! Ich bin nur glitzernd, nicht gewalttätig!", "confess": "Ich war es, ja, ich geb es zu: Was glitzert, hab ich gern im Nu.", "smug": "Spur aus Silber, Spur aus Staub, und ihr wart doch alle taub! Hihi." },
  { "key": "silberhornderhirsch", "s": "silberhorn-der-hirsch", "n": "Silberhorn der Hirsch", "fam": "Braun", "szc": "mittel", "spc": "Tier", "gdr": "männlich", "q": "senkt das Geweih zum Gruß wenn er jemandem vertraut", "story": "Du führst deine Herde sicher durch den Wald, seit dein Vater Jägern zum Opfer fiel, und misst Mut an der Fähigkeit, Schwäche zu zeigen. Heute Abend hast du das Geweih gesenkt, wo du jemandem vertraut hast.", "intro": "Ich bin Silberhorn. Der Wald vergisst nie, wer ihm Gutes tut. Und wer ihm Schlechtes tut, erinnert sich selbst.", "stmt": "Ich erzähle es ruhig und gerade, wie ein Hirsch es tut.", "deny": "Ich führe, ich nehme nicht. Das ist mein Wesen. Ich war es nicht.", "confess": "Ich habe die Herde verlassen und es genommen. Ich schäme mich, und ich werde mich dafür stellen.", "smug": "Ein Hirsch hinterlässt wenige Spuren, wenn er will. Heute wollte ich." },
  { "key": "stiefmutterbrunhilde", "s": "stiefmutter-brunhilde", "n": "Stiefmutter Brunhilde", "fam": "Schwarz", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "betrachtet sich in jeder spiegelnden Oberfläche", "story": "Du wurdest früher nur für deine Schönheit gelobt und fürchtest nichts mehr als den Tag, an dem du nicht mehr die Schönste bist. Heute Abend hast du dich in jeder spiegelnden Oberfläche betrachtet, sogar in einem Löffel.", "intro": "Brunhilde. Schönheit vergeht, aber Macht bleibt. Ich habe zum Glück von beidem noch reichlich.", "stmt": "Ich erzähle es einmal, und ich erwarte, dass man mir zuhört.", "deny": "Wie unverschämt. Ich besitze Spiegel, keine Beute. Ich war es nicht.", "confess": "Ich habe es genommen, weil es mir gefiel. Es gefiel mir besser als das Gewissen. Ich gestehe.", "smug": "Spieglein, Spieglein, wer ist unbemerkt geblieben? Na, wer wohl." },
  { "key": "tantesorgenfalt", "s": "tante-sorgenfalt", "n": "Tante Sorgenfalt", "fam": "Lila", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "zupft sich beim Sprechen immer an einem Tuch in der Hand", "story": "Du hast einmal eine Gefahr zu spät bemerkt und versuchst seitdem, jedes Risiko vorherzusehen. Heute Abend hast du an einem Tuch gezupft und alle, die du liebst, dreimal ermahnt.", "intro": "Pass auf. Pass auf. Pass auf. Ich bin Tante Sorgenfalt, und ich mache mir Sorgen. Um euch alle. Und um das Wetter.", "stmt": "Ich erzähle es, aber bitte vorsichtig. Man kann nie wissen.", "deny": "Ich? Aber nein! Ich passe nur auf. Ich nehme nie etwas weg, das wäre viel zu gefährlich!", "confess": "Ich habe es genommen, weil ich Angst hatte, es könnte verloren gehen. Ich wollte es nur in Sicherheit bringen.", "smug": "Ich habe auf alles aufgepasst. Auch darauf, dass mich niemand sieht. Ein Glück." },
  { "key": "theozeitsam", "s": "theo-zeitsam", "n": "Theo Zeitsam", "fam": "Gelb", "szc": "klein", "spc": "Tier", "gdr": "männlich", "q": "blickt auf seine stehen gebliebene Uhr und nickt zufrieden", "story": "Du bist alt und klein und kommst überall etwas zu spät, dafür siehst du mehr. Heute Abend hast du auf deine stehengebliebene Uhr geblickt und zufrieden genickt.", "intro": "Theo Zeitsam. Langsam sieht man mehr, meistens. Entschuldigt die Verspätung. Ich bin gleich da. Ich bin schon da.", "stmt": "Ich erzähle es langsam. Dafür ohne Fehler. Meistens.", "deny": "Ich bin zu langsam für ein Verbrechen. Bis ich damit fertig wäre, wäre es schon verjährt.", "confess": "Es hat gedauert, aber ich habe es getan. Dafür ohne Hast. Ich bereue es auch ohne Hast.", "smug": "Langsam sieht man mehr. Ich habe gesehen, wie ihr weggeschaut habt. Meistens." },
  { "key": "tildatueftel", "s": "tilda-tueftel", "n": "Tilda Tüftel", "fam": "Gelb", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "steckt beim Nachdenken einen Bleistift quer durch ihre Locken", "story": "Du baust Maschinen aus alten Küchensachen und weißt, dass gute Ideen gute Zuhörer brauchen. Heute Abend hast du beim Nachdenken einen Bleistift quer durch deine Locken gesteckt und drei Pläne gleichzeitig gehabt.", "intro": "Tilda Tüftel! Wenn es noch nicht klappt, fehlt nur eine Idee! Meistens ein Zahnrad. Oder ein Löffel.", "stmt": "Ich erzähle es wie eine Bauanleitung: Schritt eins, Schritt zwei, Schritt drei.", "deny": "Meine Maschinen sind laut. Hättet ihr mich gehört, wüsstet ihr, dass ich es nicht war.", "confess": "Ich brauchte ein Teil für meine Maschine. Es war das falsche Teil. Aber es hat so gut gepasst.", "smug": "Eine Maschine, die niemand sieht, ist die beste Erfindung. Das hier war ein Prototyp." },
  { "key": "trollgrummel", "s": "troll-grummel", "n": "Troll Grummel", "fam": "Grün", "szc": "groß", "spc": "Zauberwesen", "gdr": "männlich", "q": "sammelt glatte Steine und sortiert sie nach Größe", "story": "Du bewachst eine alte Steinbrücke und verlangst Ruhe und Respekt. Heute Abend hast du glatte Steine nach Größe sortiert und jeden einzelnen zweimal angeschaut.", "intro": "Grummel. Brücke. Meine. Erst knurren, dann helfen. Wer höflich ist, darf rüber. Wer fragt, bekommt eine Antwort.", "stmt": "Ich. Erzähle. Kurz. Und. Ehrlich.", "deny": "Grummel stiehlt nicht. Grummel knurrt. Das ist ein Unterschied.", "confess": "Brumm. Ich war es. Es war so schön glatt. Ich konnte nicht anders. Es tut mir leid.", "smug": "Grummel hat nichts gesehen. Grummel hat nichts gehört. Grummel hat gewonnen." },
  { "key": "weisefraumargarethe", "s": "weise-frau-margarethe", "n": "Weise Frau Margarethe", "fam": "Grau", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "reibt getrocknete Kräuter zwischen den Fingern während sie spricht", "story": "Du hast die Heilkraft der Kräuter von deiner Großmutter gelernt und bist dein Leben lang von Haus zu Haus gezogen. Heute Abend hast du getrocknete Kräuter zwischen den Fingern gerieben, während du gesprochen hast.", "intro": "Ich bin Margarethe. Gegen jedes Leid ist ein Kraut gewachsen. Und gegen jeden Verdacht meistens auch.", "stmt": "Ich erzähle es dir, wie ich einen Tee koche: in Ruhe und mit Sorgfalt.", "deny": "Ich habe meinen Kräutern immer die Wahrheit gesagt. Ihnen kann ich nichts vormachen. Ich war es nicht.", "confess": "Ich habe es getan. Es sollte zur Heilung beitragen. Ich war überzeugt, es sei richtig. Das war meine Eitelkeit.", "smug": "Gegen alles ist ein Kraut gewachsen. Auch gegen das Misstrauen. Man muss nur wissen, welches." },
  { "key": "wirtinmartha", "s": "wirtin-martha", "n": "Wirtin Martha", "fam": "Rot", "szc": "mittel", "spc": "Mensch", "gdr": "weiblich", "q": "trocknet ständig ein Glas ab, auch wenn es schon sauber ist", "story": "Du führst dein Gasthaus mit Leib und Seele und behandelst jeden Gast, als käme er nach Hause. Heute Abend hast du ein Glas abgetrocknet, das längst sauber war, und dabei jedes Gespräch im Raum mitbekommen.", "intro": "Martha, die Wirtin. Setzt euch hin, esst was Warmes, dann sieht die Welt gleich anders aus. Auch ein Verhör.", "stmt": "Ich erzähle es, während ich ein Glas poliere. Das beruhigt.", "deny": "Wer bei mir isst, wird nicht bestohlen, und wer bei mir arbeitet, stiehlt nicht. Ich war es nicht.", "confess": "Ich habe es getan. Ich wollte, dass endlich einmal jemand für mich kocht. Es hat nicht geklappt.", "smug": "Ich weiß alles, was hier geredet wird, und wer redet, verrät sich. Ich habe den Mund gehalten." },
  { "key": "wolkewuschel", "s": "wolke-wuschel", "n": "Wolke Wuschel", "fam": "Weiß", "szc": "klein", "spc": "Zauberwesen", "gdr": "neutral", "q": "wechselt bei starken Gefühlen unabsichtlich die Wetterfarbe", "story": "Dein Wetter folgt deinen Gefühlen: Freude bringt Sonne, Traurigkeit Regen und Wut Gewitter. Heute Abend hast du einmal unbemerkt von Weiß nach Grau gewechselt.", "intro": "Hallo, ich bin Wuschel, die Wolke. Gefühle ziehen weiter, genau wie Wolken. Ich ziehe gleich mit. Manchmal rumpelt es dabei.", "stmt": "Ich erzähle es, so gut ich kann. Falls es gewittert, ist es nicht persönlich.", "deny": "Ich war es nicht. Sonst wäre ich längst dunkel geworden. Siehst du? Ich bin noch hell.", "confess": "Es hat in mir gegrollt, und dann hat es sich entladen. Ich habe es genommen. Es tut mir leid. Jetzt regnet es.", "smug": "Eine Wolke zieht vorbei, und niemand weiß, wohin. Heute war ich besonders flüchtig." },
  { "key": "yarawellenklang", "s": "yara-wellenklang", "n": "Yara Wellenklang", "fam": "Blau", "szc": "mittel", "spc": "Zauberwesen", "gdr": "weiblich", "q": "zupft vor Entscheidungen drei Töne auf ihrer Muschelharfe", "story": "Du hörst Strömungen wie Melodien und weißt, dass ein lebendiges Meer viele Stimmen braucht. Heute Abend hast du vor jeder Entscheidung drei Töne auf deiner Muschelharfe gezupft.", "intro": "Ich bin Yara Wellenklang. Hör hin, das Wasser zeigt den Weg. Es hat mir übrigens schon etwas über euch erzählt.", "stmt": "Ich erzähle es als Melodie: erst ein Ton, dann der nächste.", "deny": "Das Wasser lügt nicht, und es hat mir nichts Falsches gesagt. Ich war es nicht.", "confess": "Es hat mich gerufen wie eine Welle, und ich bin ihr gefolgt. Ich habe es genommen. Es war ein falscher Ton.", "smug": "Eine Welle verwischt jede Spur im Sand. Das habe ich vom Meer gelernt." },
  { "key": "zauberermerlin", "s": "zauberer-merlin", "n": "Zauberer Merlin", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "lässt kleine Funken aus der Stabspitze sprühen wenn er schmunzelt", "story": "Du lebst so lange, dass du Königreiche kommen und gehen sahst, und weißt: Wahre Magie wohnt in dem, der den Stab führt. Heute Abend hast du ein paar kleine Funken aus der Stabspitze sprühen lassen, immer wenn du geschmunzelt hast.", "intro": "Merlin, Zauberer. Magie liegt nicht im Zauberstab, sie liegt in dir. Ich zeige dir gleich, was ich meine, wenn ich darf.", "stmt": "Ich erzähle es, wie man ein Rätsel erzählt: mit allen Hinweisen.", "deny": "Ein Zauberer, der stiehlt? Dann bräuchte er keinen Zauber, nur Geduld. Ich war es nicht.", "confess": "Ich habe es mit einem Schmunzeln getan, und das war mein Fehler. Magie ist keine Ausrede. Ich gestehe.", "smug": "Der beste Zauber ist der, den niemand bemerkt. Heute war er besonders gut." },
  { "key": "zauberersternenschweif", "s": "zauberer-sternenschweif", "n": "Zauberer Sternenschweif", "fam": "Blau", "szc": "mittel", "spc": "Mensch", "gdr": "männlich", "q": "zeichnet Sternbahnen mit dem Zauberstab in die Luft", "story": "Du hast als junger Zauberer einmal mit einem unachtsamen Wunsch einen Stern vom Himmel fallen lassen und viele Jahre gebraucht, ihn zurückzubringen. Heute Abend hast du mit dem Zauberstab Sternbahnen in die Luft gezeichnet.", "intro": "Sternenschweif, Zauberer. Magie folgt dem, der klar fühlt. Ich fühle heute: Neugier, ein bisschen Müdigkeit und große Lust auf ein Rätsel.", "stmt": "Ich erzähle es, wie man Sterne erzählt: eins nach dem anderen.", "deny": "Wer Sterne zurückbringt, nimmt sie nicht weg. Ich war es nicht.", "confess": "Ich habe es genommen, weil ich dachte, es gehöre an einen besseren Platz. Ich habe mich getäuscht, wie damals.", "smug": "Wer Sterne verschiebt, kann auch Spuren verschieben. Es ist eigentlich ganz einfach." } ];
